package com.carrot.tmaprouteprobe;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.view.accessibility.*;import android.widget.*;import org.json.*;import java.lang.reflect.*;import java.util.*;import java.io.*;import java.nio.file.*;
/** Stationary integration test: real native routes, actual signed inter-app switch buttons, no GPS injection. */
public final class KisaSwitchRunner extends Instrumentation {
 JSONObject report=new JSONObject();File dir;ClassLoader cl;Object manager;Activity preview;String token="";
 static Object field(Object o,String name)throws Exception{Class<?> c=o instanceof Class?(Class<?>)o:o.getClass();Field f=c.getDeclaredField(name);f.setAccessible(true);return f.get(o instanceof Class?null:o);}
 static Object get(Object o,String name)throws Exception{Method m=o.getClass().getMethod(name);m.setAccessible(true);return m.invoke(o);}
 static void check(boolean b,String why)throws Exception{if(!b)throw new Exception(why);}
 AccessibilityNodeInfo text(AccessibilityNodeInfo root,String label){if(root==null)return null;String value=String.valueOf(root.getText()).replace(" ","");if(label.equals(value)||label.equals(String.valueOf(root.getContentDescription()).replace(" ","")))return root;for(int i=0;i<root.getChildCount();i++){AccessibilityNodeInfo found=text(root.getChild(i),label);if(found!=null)return found;}return null;}
 boolean click(String label){AccessibilityNodeInfo node=text(getUiAutomation().getRootInActiveWindow(),label);while(node!=null&&!node.isClickable())node=node.getParent();return node!=null&&node.performAction(AccessibilityNodeInfo.ACTION_CLICK);}
 void main(Throwing action){runOnMainSync(()->{try{action.run();}catch(Exception e){throw new RuntimeException(e);}});}interface Throwing{void run()throws Exception;}
 JSONObject health()throws Exception{return (JSONObject)cl.loadClass("com.carrot.naverroute.RecordingHealth").getMethod("snapshot").invoke(null);}
 void waitOwner(String owner)throws Exception{long until=SystemClock.elapsedRealtime()+18000;while(SystemClock.elapsedRealtime()<until){Thread.sleep(300);JSONObject h=health();if(owner.equals(h.optString("guidance_owner"))&&"active".equals(h.optString("status")))return;}throw new Exception("Owner switch did not complete: "+owner+" current="+health());}
 void shot(String name)throws Exception{android.graphics.Bitmap b=getUiAutomation().takeScreenshot();try(FileOutputStream f=new FileOutputStream(new File(dir,name))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}b.recycle();}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle out=new Bundle();try{Context c=getTargetContext();cl=c.getClassLoader();dir=new File(c.getExternalFilesDir(null),"kisa_switch_probe");dir.mkdirs();android.accessibilityservice.AccessibilityServiceInfo info=getUiAutomation().getServiceInfo();info.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_INCLUDE_NOT_IMPORTANT_VIEWS|android.accessibilityservice.AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;getUiAutomation().setServiceInfo(info);ActivityMonitor hm=addMonitor("com.skt.tmap.activity.TmapNewMainActivity",null,false);startActivitySync(c.getPackageManager().getLaunchIntentForPackage(c.getPackageName()).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(2200);Activity home=hm.getLastActivity();if(home==null)home=waitForMonitorWithTimeout(hm,3000);check(home!=null,"Home missing");final Activity h=home;main(()->cl.loadClass("com.carrot.naverroute.HomeIdleBridge").getMethod("pause",Activity.class).invoke(null,h));
  JSONObject place=new JSONObject().put("name","수학의힘 신검단캠퍼스학원").put("address","인천 검단구 고산후로 221").put("lat",37.6034634).put("lon",126.6981604);Method destination=cl.loadClass("com.carrot.naverroute.NaverPlaceSearch").getDeclaredMethod("destinationIntent",Context.class,JSONObject.class);destination.setAccessible(true);Intent open=(Intent)destination.invoke(null,c,place);preview=startActivitySync(open.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Object vm=get(preview,"p0");Object counter=field(vm,"u0");Object[] selected={null};Class<?> bridge=cl.loadClass("com.carrot.naverroute.PreviewBridge");Object[] session={null};long until=SystemClock.elapsedRealtime()+50000;
  while(SystemClock.elapsedRealtime()<until){main(()->{counter.getClass().getMethod("setValue",Object.class).invoke(counter,false);session[0]=((Map<?,?>)field(bridge,"SESSIONS")).get(vm);});if(session[0]!=null&&Boolean.TRUE.equals(field(session[0],"choiceDone"))){for(Object card:(List<?>)get(field(vm,"j0"),"getValue"))if("Traffic_Recommend".equals(String.valueOf(get(card,"getRoutePlanType"))))selected[0]=card;if(selected[0]!=null)break;}Thread.sleep(150);}
  check(selected[0]!=null,"Native comparison not ready");Object fragment=((java.lang.ref.Reference<?>)field(session[0],"fragment")).get();Class<?> callback=cl.loadClass("com.skt.tmap.mvp.fragment.TmapRoutePreviewFragment$e");Object cb=callback.getConstructor(fragment.getClass()).newInstance(fragment);List<?> ordered=(List<?>)get(field(field(vm,"k0"),"Z"),"getValue");int index=-1;for(int i=0;i<ordered.size();i++)if(get(ordered.get(i),"getRoutePlanType")==get(selected[0],"getRoutePlanType"))index=i;final int at=index;main(()->callback.getMethod("e",int.class,selected[0].getClass()).invoke(cb,at,selected[0]));Thread.sleep(400);check(click("안내시작"),"Native start button missing");manager=cl.loadClass("com.skt.tmap.engine.navigation.NavigationManager").getMethod("getInstance").invoke(null);waitOwner("tmap");token=health().getString("token");byte[] binary=((byte[])get(get(manager,"getRouteResult"),"getBinaryData")).clone();
  // Companion initially opens to establish its own route, then returns without replacing Tmap's route.
  Thread.sleep(14000);main(()->c.startActivity(c.getPackageManager().getLaunchIntentForPackage(c.getPackageName()).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_REORDER_TO_FRONT)));Thread.sleep(1200);shot("tmap-before-switch.png");report.put("signal_with_tbt",KisaSignalScreenTest.run(this,cl,new File(dir,"tmap-signal-with-tbt-real-screen.png")));check(click("네이버로전환"),"Tmap switch button not visible");waitOwner("naver");Thread.sleep(1600);shot("naver-after-switch.png");report.put("real_tmap_to_naver_button",true);check(token.equals(health().getString("token")),"Trip token changed on switch");
  check(click("티맵으로전환"),"Naver switch button not visible");waitOwner("tmap");Thread.sleep(1200);shot("tmap-after-switch.png");check(Arrays.equals(binary,(byte[])get(get(manager,"getRouteResult"),"getBinaryData")),"Tmap route rebuilt by switch");report.put("real_naver_to_tmap_button",true).put("same_trip_and_native_route_preserved",true);report.put("signal_screen",KisaSignalScreenTest.run(this,cl,new File(dir,"tmap-signal-real-screen.png")));getUiAutomation().performGlobalAction(2);Thread.sleep(1200);shot("other-app-selected-tmap.png");report.put("owner_retained_on_home",health().optString("guidance_owner").equals("tmap"));
 }catch(Throwable e){while(e.getCause()!=null)e=e.getCause();try{report.put("error",e.toString());shot("failure.png");}catch(Exception ignored){}}finally{try{if(manager!=null){cl.loadClass("com.carrot.naverroute.DualNavigation").getMethod("setGuidanceOwner",String.class).invoke(null,"tmap");main(()->manager.getClass().getMethod("stopDriving",boolean.class).invoke(manager,false));}}catch(Exception ignored){}}
 try{Files.write(new File(dir,"report.json").toPath(),report.toString(2).getBytes("UTF-8"));}catch(Exception ignored){}out.putString("report",report.toString());finish(Activity.RESULT_OK,out);}
}
